CREATE TRIGGER RefUnitSection_Version_Create
	ON RefUnitSection
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT RUS_PK, 'RUS'
	FROM inserted
GO
CREATE TRIGGER RefUnitSection_Version_Update
	ON RefUnitSection
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RUS_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER RefUnitSection_DataChangeHistory
	ON RefUnitSection
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT RUS_PK, 'RUS' FROM inserted
	UNION
	SELECT RUS_PK, 'RUS' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER RefUnitSection_DataProcessingResult_Delete
	ON RefUnitSection
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.RUS_PK
	END
GO
